local UIActivityPaySignCellNode = Class("UIActivityPaySignCellNode")
function UIActivityPaySignCellNode:__init()
    self.btnAction = nil
    self.activityData = nil
    self.data = nil
end

function UIActivityPaySignCellNode:__delete()
    self.btnAction = nil
    self.data = nil
    self.activityData = nil
    self.controller = nil
end

---HasUnlocked
---是否可以购买的逻辑
function UIActivityPaySignCellNode:HasUnlocked(showTips)
    showTips = checkBool(showTips)
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    local endTime = checkNumber(self.activityData.closeTime)
    local leftTime = endTime - curDate
    if showTips then
        if leftTime < 0 then
            GameUtils.Toast(localize("活动已经结束"))
        elseif checkNumber(self.data.hasBuy) == 0 then
            GameUtils.Toast(localize("购买之后才能解锁领取"))
        end
    end
    return leftTime > 0 and checkNumber(self.data.hasBuy) == 1
end

---SetCallBack
---设置单击回调函数
function UIActivityPaySignCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function UIActivityPaySignCellNode:Awake()
    if self.BtnNode then
        SetButtonAction(self.BtnNode, function ()
            if type(self.btnAction) == 'function' then
                if self:HasUnlocked(true) then
                    self.btnAction()
                end
            end
        end)
    end
    if self.BtnCardSigninNode then
        SetButtonAction(self.BtnCardSigninNode, function ()
            if type(self.btnAction) == 'function' then
                if self:HasUnlocked(true) then
                    self.btnAction()
                end
            end
        end)
    end
end

function UIActivityPaySignCellNode:FreshBaseUI(data, isTomorrow, activityData, hasBuy)
    self.data = data
    self.data.hasBuy = hasBuy
    self.activityData = activityData
    self:FillDayText(data.accumulativeLoginNum)
    self:FillDrawStatus(data.status, isTomorrow)
    KTool.SetActive(self.Effect, self:HasUnlocked() and checkInt(data.status) == Constants.GetStatus.Can)
    self:FillGoodsNode(data)
end

function UIActivityPaySignCellNode:FreshFinalUI(data, isTomorrow)
    self:FillDayText(data.accumulativeLoginNum)
    self:FillImgRole(data)
    self:FillDrawStatus(data.status, isTomorrow)
end
---显示天数
function UIActivityPaySignCellNode:FillDayText(day)
    self.TextNumber.text = day
end

---签到情况
function UIActivityPaySignCellNode:FillDrawStatus(status, isTomorrow)
    KTool.SetActive(self.Tomorrow, checkBool(isTomorrow))
    KTool.SetActive(self.CanReceive, self:HasUnlocked() and checkInt(status) == Constants.GetStatus.Can)
    KTool.SetActive(self.Effect, self:HasUnlocked() and checkInt(status) == Constants.GetStatus.Can)
    KTool.SetActive(self.HasReceived, self:HasUnlocked() and checkInt(status) == Constants.GetStatus.Has)
end

---填充人物立绘
function UIActivityPaySignCellNode:FillImgRole(data)
    local goodsId = data.rewards[1].goodsId
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    KTool.SetActive(self.ImgRole, isCardOrSkin)
    KTool.SetActive(self.GoodNode, not isCardOrSkin)
    KTool.SetActive(self.Effect.transform:Find("UIFX_SingleSignPanelIcon"), not isCardOrSkin)
    if isCardOrSkin then
        local path = CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(goodsId)
        CfUtils.FillImage(self.ImgRole, path)
    else
        self:FillGoodsNode(data)
    end
end

function UIActivityPaySignCellNode:FillGoodsNode(data)
    local rewards = data.rewards[1]
    if checkNumber(data.special) == 1 then
        CfUtils.SetActive(self.GoodNode, false)
        CfUtils.SetActive(self.GoodNode.transform.parent:Find("ImgBIgReward"), true)
        CfUtils.SetActive(self.GoodNode.transform.parent:Find("ImgRole"), true)
        local vo = GoodsUtils.GetGoodsVoById(rewards.goodsId)
        CfUtils.FillImage(self.GoodNode.transform.parent:Find("ImgRole"), vo.photoPath)
    else
        CfUtils.SetActive(self.GoodNode, true)
        CfUtils.SetActive(self.GoodNode.transform.parent:Find("ImgBIgReward"), false)
        CfUtils.SetActive(self.GoodNode.transform.parent:Find("ImgRole"), false)
        local nodeEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
        if nodeEnv then
            nodeEnv:SetClickButtonAction(function()
                if self:HasUnlocked() and checkInt(data.status) == Constants.GetStatus.Can then
                    if type(self.btnAction) == 'function' then
                        self.btnAction()
                    end
                else
                    self:ShowGoodsTips(rewards)
                end
            end)
            nodeEnv:Reload(
                    {
                        goodsId = checkInt(rewards.goodsId),
                        isShowNo = true, text = 'x' .. tostring(rewards.num)
                    }
            )
        end
    end

end

function UIActivityPaySignCellNode:ShowGoodsTips(rewards)
    local goodsId = rewards.goodsId
    local  vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if isTable(vo) then
        GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.descr, vo.quality, vo.id)
    end
end

function UIActivityPaySignCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return UIActivityPaySignCellNode